package com.example.tilecommerce.service;
import com.example.tilecommerce.dto.AdminDtos.*; import com.example.tilecommerce.entity.*; import com.example.tilecommerce.enumeration.Role; import com.example.tilecommerce.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class AdminService {private final ShopRepository shops;private final UserRepository users;private final CategoryRepository categories;private final PasswordEncoder encoder;
 public List<Shop> shops(){return shops.findAll();} @Transactional public Shop shop(ShopRequest r){Shop s=new Shop();s.setName(r.name());s.setDescription(r.description());s.setAddress(r.address());s.setCity(r.city());s.setState(r.state());s.setPostalCode(r.postalCode());s.setPhoneNumber(r.phoneNumber());s.setEmail(r.email());s.setUpiId(r.upiId());s.setPaymentPhoneNumber(r.paymentPhoneNumber());s.setBankAccountNumber(r.bankAccountNumber());s.setBankIfsc(r.bankIfsc());s.setQrCodeUrl(r.qrCodeUrl());return shops.save(s);}
 public List<User> users(){return users.findAll();} @Transactional public User user(UserRequest r){User u=new User();u.setUsername(r.username());u.setEmail(r.email());u.setPassword(encoder.encode(r.password()));u.setRole(Role.valueOf(r.role()));if(r.shopId()!=null)u.setShop(shops.findById(r.shopId()).orElseThrow());return users.save(u);}
 public List<Category> categories(){return categories.findAll();} @Transactional public Category category(CategoryRequest r){Category c=new Category();c.setName(r.name());c.setDescription(r.description());return categories.save(c);}
}
